var ErrNotFound = errors.New("surcharge override not found")

type Override struct {
	ID            int64
	LaneID        string
	SurchargeType string
	Amount        decimal.Decimal
	Reason        string
	ActiveFrom    time.Time
	ActiveUntil   *time.Time // nil = open-ended
}

type CreateParams struct {
	LaneID        string
	SurchargeType string
	Amount        decimal.Decimal
	Reason        string
	ActiveFrom    time.Time // zero = now
	ActiveUntil   *time.Time
}

type Store struct{ q db.Querier }

func NewStore(q db.Querier) *Store { return &Store{q: q} }

func (s *Store) Create(ctx context.Context, p CreateParams) (Override, error) {
	if p.LaneID == "" || p.SurchargeType == "" {
		return Override{}, errors.New("lane id and surcharge type are required")
	}
	if p.Amount.IsNegative() {
		return Override{}, errors.New("amount must not be negative")
	}
	if p.ActiveUntil != nil && !p.ActiveFrom.IsZero() && !p.ActiveUntil.After(p.ActiveFrom) {
		return Override{}, errors.New("active_until must be after active_from")
	}
	row, err := s.q.CreateSurchargeOverride(ctx, db.CreateSurchargeOverrideParams{
		LaneID: p.LaneID, SurchargeType: p.SurchargeType, Amount: p.Amount, Reason: p.Reason,
		ActiveFrom: toTS(&p.ActiveFrom), ActiveUntil: toTS(p.ActiveUntil),
	})
	if err != nil {
		return Override{}, fmt.Errorf("create surcharge override: %w", err)
	}
	return fromRow(row), nil
}

func (s *Store) GetActiveByLane(ctx context.Context, laneID string) (Override, error) {
	row, err := s.q.GetActiveSurchargeOverrideByLane(ctx, laneID)
	if errors.Is(err, pgx.ErrNoRows) {
		return Override{}, ErrNotFound
	}
	if err != nil {
		return Override{}, fmt.Errorf("get surcharge override for lane %q: %w", laneID, err)
	}
	return fromRow(row), nil
}

func (s *Store) ListActive(ctx context.Context) ([]Override, error) {
	rows, err := s.q.ListActiveSurchargeOverrides(ctx)
	if err != nil {
		return nil, fmt.Errorf("list active surcharge overrides: %w", err)
	}
	out := make([]Override, 0, len(rows))
	for _, r := range rows {
		out = append(out, fromRow(r))
	}
	return out, nil
}

func fromRow(r db.SurchargeOverride) Override {
	o := Override{ID: r.ID, LaneID: r.LaneID, SurchargeType: r.SurchargeType,
		Amount: r.Amount, Reason: r.Reason, ActiveFrom: r.ActiveFrom.Time}
	if r.ActiveUntil.Valid {
		t := r.ActiveUntil.Time
		o.ActiveUntil = &t
	}
	return o
}

func toTS(t *time.Time) pgtype.Timestamptz {
	if t == nil || t.IsZero() {
		return pgtype.Timestamptz{}
	}
	return pgtype.Timestamptz{Time: *t, Valid: true}
}
