package quote

import (
	"context"
	"sync"
	"time"

	"golang.org/x/sync/singleflight"
)

type Surcharge struct {
	Amount   int64 // minor units
	Currency string
}

// SurchargeLookup is whatever currently backs the surcharge lookup (DB, rate API, ...).
type SurchargeLookup interface {
	Lookup(ctx context.Context, lane string, date time.Time) (Surcharge, error)
}

type cacheKey struct {
	lane string
	date string // YYYY-MM-DD
}

type cacheEntry struct {
	val     Surcharge
	expires time.Time
}

// CachedSurcharges wraps a SurchargeLookup with a TTL cache keyed by (lane, date).
type CachedSurcharges struct {
	next       SurchargeLookup
	ttl        time.Duration
	maxEntries int
	now        func() time.Time

	mu    sync.RWMutex
	m     map[cacheKey]cacheEntry
	group singleflight.Group
}

func NewCachedSurcharges(next SurchargeLookup) *CachedSurcharges {
	return &CachedSurcharges{
		next:       next,
		ttl:        60 * time.Second,
		maxEntries: 10_000,
		now:        time.Now,
		m:          make(map[cacheKey]cacheEntry),
	}
}

func (c *CachedSurcharges) Lookup(ctx context.Context, lane string, date time.Time) (Surcharge, error) {
	k := cacheKey{lane: lane, date: date.UTC().Format("2006-01-02")}

	if v, ok := c.get(k); ok {
		return v, nil
	}

	// Collapse concurrent misses for the same key into one upstream call.
	// The shared call is detached from any single caller's cancellation.
	ch := c.group.DoChan(k.lane+"|"+k.date, func() (any, error) {
		upCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 5*time.Second)
		defer cancel()
		v, err := c.next.Lookup(upCtx, lane, date)
		if err != nil {
			return Surcharge{}, err // errors are never cached
		}
		c.put(k, v)
		return v, nil
	})

	select {
	case <-ctx.Done():
		return Surcharge{}, ctx.Err()
	case r := <-ch:
		if r.Err != nil {
			return Surcharge{}, r.Err
		}
		return r.Val.(Surcharge), nil
	}
}

func (c *CachedSurcharges) get(k cacheKey) (Surcharge, bool) {
	c.mu.RLock()
	e, ok := c.m[k]
	c.mu.RUnlock()
	if !ok || !c.now().Before(e.expires) {
		return Surcharge{}, false
	}
	return e.val, true
}

func (c *CachedSurcharges) put(k cacheKey, v Surcharge) {
	now := c.now()
	c.mu.Lock()
	defer c.mu.Unlock()
	if len(c.m) >= c.maxEntries {
		for key, e := range c.m { // drop expired entries first
			if !now.Before(e.expires) {
				delete(c.m, key)
			}
		}
		for key := range c.m { // still full: evict arbitrary entries
			if len(c.m) < c.maxEntries {
				break
			}
			delete(c.m, key)
		}
	}
	c.m[k] = cacheEntry{val: v, expires: now.Add(c.ttl)}
}
```

