// Package surcharge: cache-aside wrapper around the fuel surcharge lookup.
package surcharge

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"golang.org/x/sync/singleflight"
)

const (
	DefaultTTL = 60 * time.Second
	keyPrefix  = "kestrel:surcharge:v1:" // bump v1 to invalidate everything on a schema change
)

// Surcharge is the lookup result. Money is integer minor units to avoid
// float and rounding drift (see the half-up vs banker's mismatch).
type Surcharge struct {
	LaneID      string `json:"lane_id"`
	Date        string `json:"date"` // YYYY-MM-DD
	AmountCents int64  `json:"amount_cents"`
	Currency    string `json:"currency"`
}

// Lookup is the uncached source (Postgres via sqlc in practice).
type Lookup interface {
	Surcharge(ctx context.Context, laneID string, date time.Time) (Surcharge, error)
}

// Store is the subset of Valkey we need. ErrMiss means key absent.
type Store interface {
	Get(ctx context.Context, key string) ([]byte, error)
	Set(ctx context.Context, key string, val []byte, ttl time.Duration) error
	Del(ctx context.Context, key string) error
}

var ErrMiss = errors.New("cache miss")

type CachedLookup struct {
	next  Lookup
	store Store
	ttl   time.Duration
	sf    singleflight.Group
}

func NewCachedLookup(next Lookup, store Store, ttl time.Duration) *CachedLookup {
	if ttl <= 0 {
		ttl = DefaultTTL
	}
	return &CachedLookup{next: next, store: store, ttl: ttl}
}

func key(laneID string, date time.Time) string {
	return fmt.Sprintf("%s%s:%s", keyPrefix, laneID, date.UTC().Format("2006-01-02"))
}

// Surcharge is cache-aside. Cache failures never fail the quote: we log
// and fall through to the source of truth.
func (c *CachedLookup) Surcharge(ctx context.Context, laneID string, date time.Time) (Surcharge, error) {
	k := key(laneID, date)

	if b, err := c.store.Get(ctx, k); err == nil {
		var s Surcharge
		if err := json.Unmarshal(b, &s); err == nil {
			return s, nil
		}
		slog.WarnContext(ctx, "surcharge cache: bad payload", "key", k)
	} else if !errors.Is(err, ErrMiss) {
		slog.WarnContext(ctx, "surcharge cache: get failed", "key", k, "err", err)
	}

	// Collapse concurrent misses for the same key into one DB call.
	v, err, _ := c.sf.Do(k, func() (any, error) {
		s, err := c.next.Surcharge(ctx, laneID, date)
		if err != nil {
			return Surcharge{}, err // errors are not cached
		}
		if b, err := json.Marshal(s); err == nil {
			if err := c.store.Set(ctx, k, b, c.ttl); err != nil {
				slog.WarnContext(ctx, "surcharge cache: set failed", "key", k, "err", err)
			}
		}
		return s, nil
	})
	if err != nil {
		return Surcharge{}, err
	}
	return v.(Surcharge), nil
}

// Invalidate drops one entry. Call it from the surcharge-update path so a
// fuel surcharge change doesn't wait out the TTL.
func (c *CachedLookup) Invalidate(ctx context.Context, laneID string, date time.Time) error {
	return c.store.Del(ctx, key(laneID, date))
}
