import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"time"

	"golang.org/x/sync/singleflight"
)

const (
	TTL       = 60 * time.Second
	keyPrefix = "surcharge:v1:" // bump the version if Surcharge's shape changes
)

// Surcharge is a placeholder; use the service's real type. Keep money as
// integer minor units or a string decimal so a cache round trip never rounds.
type Surcharge struct {
	LaneID    string `json:"lane_id"`
	Date      string `json:"date"` // YYYY-MM-DD
	AmountMin int64  `json:"amount_minor"`
	Currency  string `json:"currency"`
}

// Lookup is the existing, uncached surcharge lookup.
type Lookup interface {
	Surcharge(ctx context.Context, lane string, date time.Time) (Surcharge, error)
}

// Store is the small slice of the Valkey client we need.
// Get returns (nil, nil) on a miss.
type Store interface {
	Get(ctx context.Context, key string) ([]byte, error)
	Set(ctx context.Context, key string, val []byte, ttl time.Duration) error
	Del(ctx context.Context, keys ...string) error
}

type Cached struct {
	next  Lookup
	store Store
	log   *slog.Logger
	group singleflight.Group
}

func NewCached(next Lookup, store Store, log *slog.Logger) *Cached {
	return &Cached{next: next, store: store, log: log}
}

func key(lane string, date time.Time) string {
	return fmt.Sprintf("%s%s:%s", keyPrefix, lane, date.UTC().Format("2006-01-02"))
}

func (c *Cached) Surcharge(ctx context.Context, lane string, date time.Time) (Surcharge, error) {
	k := key(lane, date)

	if b, err := c.store.Get(ctx, k); err != nil {
		c.log.WarnContext(ctx, "surcharge cache get failed", "err", err) // fail open
	} else if b != nil {
		var s Surcharge
		if err := json.Unmarshal(b, &s); err == nil {
			return s, nil
		}
		c.log.WarnContext(ctx, "surcharge cache decode failed", "key", k)
	}

	// Collapse concurrent misses for the same key into one backend call.
	v, err, _ := c.group.Do(k, func() (any, error) {
		s, err := c.next.Surcharge(ctx, lane, date)
		if err != nil {
			return Surcharge{}, err // never cache errors
		}
		if b, err := json.Marshal(s); err == nil {
			if err := c.store.Set(ctx, k, b, TTL); err != nil {
				c.log.WarnContext(ctx, "surcharge cache set failed", "err", err)
			}
		}
		return s, nil
	})
	if err != nil {
		return Surcharge{}, err
	}
	return v.(Surcharge), nil
}

// Invalidate drops one lane/date entry. Call it from the fuel-surcharge
// update path so readers don't wait out the TTL.
func (c *Cached) Invalidate(ctx context.Context, lane string, date time.Time) error {
	return c.store.Del(ctx, key(lane, date))
}
