package surchargecache

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"golang.org/x/sync/singleflight"
)

const TTL = 60 * time.Second

type Surcharge struct { // adjust to the real type
	Percent   float64   `json:"percent"`
	UpdatedAt time.Time `json:"updated_at"`
}

type Loader interface {
	Surcharge(ctx context.Context, lane string, date time.Time) (Surcharge, error)
}

type Store interface {
	Get(ctx context.Context, key string) ([]byte, error) // ErrMiss if absent
	Set(ctx context.Context, key string, val []byte, ttl time.Duration) error
	Del(ctx context.Context, key string) error
}

var ErrMiss = errors.New("surchargecache: miss")

type Cache struct {
	loader  Loader
	store   Store
	group   singleflight.Group
	OnError func(op string, err error) // wire to logs/metrics
}

func New(l Loader, s Store) *Cache { return &Cache{loader: l, store: s} }

func key(lane string, d time.Time) string {
	return "surcharge:v1:" + lane + ":" + d.Format("2006-01-02")
}

func (c *Cache) report(op string, err error) {
	if c.OnError != nil {
		c.OnError(op, err)
	}
}

// Surcharge serves from cache, else loads and caches. Cache errors never
// fail the lookup; concurrent misses share one load.
func (c *Cache) Surcharge(ctx context.Context, lane string, d time.Time) (Surcharge, error) {
	k := key(lane, d)
	b, err := c.store.Get(ctx, k)
	switch {
	case err == nil:
		var s Surcharge
		if uerr := json.Unmarshal(b, &s); uerr == nil {
			return s, nil
		} else {
			c.report("decode", uerr)
		}
	case !errors.Is(err, ErrMiss):
		c.report("get", err)
	}

	v, err, _ := c.group.Do(k, func() (any, error) {
		s, err := c.loader.Surcharge(ctx, lane, d)
		if err != nil {
			return Surcharge{}, err
		}
		if b, merr := json.Marshal(s); merr == nil {
			if serr := c.store.Set(ctx, k, b, TTL); serr != nil {
				c.report("set", serr)
			}
		}
		return s, nil
	})
	if err != nil {
		return Surcharge{}, err
	}
	return v.(Surcharge), nil
}

// Invalidate drops an entry so a surcharge update doesn't wait out the TTL.
func (c *Cache) Invalidate(ctx context.Context, lane string, d time.Time) error {
	return c.store.Del(ctx, key(lane, d))
}
