}

type Lookup interface {
	Surcharge(ctx context.Context, lane string, date time.Time) (Surcharge, error)
}

type Store interface {
	Get(ctx context.Context, key string) ([]byte, bool, error)
	Set(ctx context.Context, key string, val []byte, ttl time.Duration) error
	Del(ctx context.Context, key string) error
}

type Cached struct {
	next  Lookup
	store Store
	ttl   time.Duration
	group singleflight.Group
}

func NewCached(next Lookup, store Store, ttl time.Duration) *Cached {
	if ttl <= 0 {
		ttl = DefaultTTL
	}
	return &Cached{next: next, store: store, ttl: ttl}
}

func key(lane string, date time.Time) string {
	return fmt.Sprintf("surcharge:v1:%s:%s", lane, date.UTC().Format("2006-01-02"))
}

// Cache failures never fail a quote: log and fall through to the source.
func (c *Cached) Surcharge(ctx context.Context, lane string, date time.Time) (Surcharge, error) {
	k := key(lane, date)

	if raw, ok, err := c.store.Get(ctx, k); err != nil {
		slog.WarnContext(ctx, "surcharge cache get failed", "key", k, "err", err)
	} else if ok {
		var s Surcharge
		if json.Unmarshal(raw, &s) == nil {
			return s, nil
		}
		slog.WarnContext(ctx, "surcharge cache entry corrupt", "key", k)
	}

	// Collapse concurrent misses for one key into a single DB call.
	v, err, _ := c.group.Do(k, func() (any, error) {
		s, err := c.next.Surcharge(ctx, lane, date)
		if err != nil {
			return Surcharge{}, err
		}
		if raw, err := json.Marshal(s); err == nil {
			if err := c.store.Set(ctx, k, raw, c.ttl); err != nil {
				slog.WarnContext(ctx, "surcharge cache set failed", "key", k, "err", err)
			}
		}
		return s, nil
	})
	if err != nil {
		return Surcharge{}, err
	}
	return v.(Surcharge), nil
}

// Call from the fuel-surcharge update path; anything missed expires within ttl.
func (c *Cached) Invalidate(ctx context.Context, lane string, date time.Time) error {
	return c.store.Del(ctx, key(lane, date))
}
