	"github.com/valkey-io/valkey-go"
)

type ValkeyStore struct{ Client valkey.Client }

func (v ValkeyStore) Get(ctx context.Context, key string) ([]byte, bool, error) {
	b, err := v.Client.Do(ctx, v.Client.B().Get().Key(key).Build()).AsBytes()
	if valkey.IsValkeyNil(err) {
		return nil, false, nil
	}
	return b, err == nil, err
}

func (v ValkeyStore) Set(ctx context.Context, key string, val []byte, ttl time.Duration) error {
	return v.Client.Do(ctx, v.Client.B().Set().Key(key).Value(string(val)).Px(ttl).Build()).Error()
}

func (v ValkeyStore) Del(ctx context.Context, key string) error {
	return v.Client.Do(ctx, v.Client.B().Del().Key(key).Build()).Error()
}
